/*
 * A106323  Smaller of number pair whose squares are reversals of each other,
 *          with no leading zeros allowed.
 * https://oeis.org/A106323
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   a(n) = the smaller member of each pair of integers (x,y) with
 *            x<y, such that x² and y² are reversals of each other in decimal
 *            representation, with no leading zeros allowed. The sequence is
 *            generated by testing successive integers for this property
 * Range:     u8 none, u16 n <= 4, u32 n <= 40, u64 n <= 40, u128 n <= 40,
 *            big any n
 * Helpers:   isqrt, rev
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include "../utils/rev.h"
#include "../utils/isqrt.h"

seq_t a(idx_t n) {
    if (n == 0) return 0;          /* Safety: offset 1, but handle n==0 gracefully */

    idx_t found = 0;
    for (idx_t x = 1;; ++x) {
        /* Skip numbers whose squares would end in 0 as that would create
           leading zeros on reversing.  x%10==0 iff x²%10==0. */
        if (x % 10 == 0) continue;

        seq_t sq = (seq_t)x * (seq_t)x;
        if (sq % 10 == 0) continue; /* Redundant, but safe */

        seq_t rev_sq = rev(sq);
        if (rev_sq % 10 == 0) continue; /* Reversed square would have leading zeros */

        seq_t y = isqrt(rev_sq);
        if (y * y == rev_sq) {         /* y² == reversed square? */
            seq_t xt = (seq_t)x;
            if (y > xt) {              /* Keep the smaller of the pair */
                ++found;
                if (found == n) return xt;
            }
        }
    }
}
